function lire(s) {
  const p = s.trim().split(/\s+/).map(c => c.split(',').map(Number));
  let x0 = 1e9, x1 = -1e9, y0 = 1e9, y1 = -1e9;
  for (const [x, y] of p) { x0 = Math.min(x0, x); x1 = Math.max(x1, x); y0 = Math.min(y0, y); y1 = Math.max(y1, y); }
  return { p, x0, x1, y0, y1 };
}
const TP = TERRE.map(lire), MP = MERS.map(lire);
function dans(P, x, y) {
  if (x < P.x0 || x > P.x1 || y < P.y0 || y > P.y1) return false;
  const p = P.p; let c = false;
  for (let i = 0, j = p.length - 1; i < p.length; j = i++) {
    const xi = p[i][0], yi = p[i][1], xj = p[j][0], yj = p[j][1];
    if ((yi > y) !== (yj > y) && x < (xj - xi) * (y - yi) / (yj - yi) + xi) c = !c;
  }
  return c;
}
function estTerre(lon, lat) {
  if (lat < -69) return true;
  for (const P of MP) if (dans(P, lon, lat)) return false;
  for (const P of TP) if (dans(P, lon, lat) || dans(P, lon + 360, lat)) return true;
  return false;
}
// la grille : des rangees de latitude, autant de points par degre a chaque latitude (pas regulier sur la sphere)
const GRILLES = {};
function grille(pas) {
  if (GRILLES[pas]) return GRILLES[pas];
  const out = [];
  for (let lat = -90 + pas / 2; lat < 90; lat += pas) {
    const n = Math.max(1, Math.round(360 * Math.cos(lat * Math.PI / 180) / pas));
    const dec = (Math.round((lat + 90) / pas) % 2) * 0.5;   // une rangee sur deux decalee d'un demi-pas
    for (let i = 0; i < n; i++) {
      let lon = -180 + (i + dec) * 360 / n;
      if (!estTerre(lon, lat)) continue;
      const a = lat * Math.PI / 180, b = lon * Math.PI / 180;
      out.push(Math.cos(a) * Math.sin(b), Math.sin(a), Math.cos(a) * Math.cos(b));
    }
  }
  return (GRILLES[pas] = new Float32Array(out));
}

